let numPoints = 100; // number of points to draw
let pointDiameter = 5; // diameter of each point
let lineLength = 20; // length of lines coming out of points
let lineWidth = 2; // width of lines
let colors = ['#FF0000', '#00FF00', '#0000FF']; // colors of lines

function setup() {
  createCanvas(400, 400);
  noStroke();
}

function draw() {
  background(220);
  for (let i = 0; i < numPoints; i++) {
    let x = random(width);
    let y = random(height);
    let c = random(colors);

    // draw point
    fill(c);
    ellipse(x, y, pointDiameter, pointDiameter);

    // draw line coming out of point
    stroke(c);
    strokeWeight(lineWidth);
    line(x, y, x + lineLength, y + lineLength);
  }
}
```
