#include <WiFi.h>
#include <FirebaseESP32.h>

#define FIREBASE_HOST "your-firebase-database.firebaseio.com"
#define FIREBASE_AUTH "your-firebase-secret"

#define WIFI_SSID "your-wifi-ssid"
#define WIFI_PASSWORD "your-wifi-password"

FirebaseData firebaseData;

void setup() {
  Serial.begin(115200);

  // Connect to Wi-Fi
  WiFi.begin(WIFI_SSID, WIFI_PASSWORD);
  while (WiFi.status() != WL_CONNECTED) {
    delay(1000);
    Serial.println("Connecting to WiFi...");
  }
  Serial.println("Connected to WiFi");

  // Initialize Firebase
  Firebase.begin(FIREBASE_HOST, FIREBASE_AUTH);
}

void loop() {
  // Create a JSON object
  String jsonString = "{\"name\":\"John\",\"age\":30,\"city\":\"New York\"}";
  FirebaseJson json;
  json.setJsonData(jsonString);

  // Send the JSON data to Firebase
  Firebase.pushJSON(firebaseData, "/users", json);
  if (firebaseData.dataAvailable()) {
    Serial.println(firebaseData.responseCode());
    Serial.println(firebaseData.stringData());
  }

  delay(5000);
}
```
In the `setup()` function, we first connect to Wi-Fi and then initialize the Firebase library with the database URL and authentication secret.

In the `loop()` function, we create a JSON object using the `FirebaseJson` class and set its data to a sample JSON string. We then use the `Firebase.pushJSON()` function to send the JSON data to the `/users` node in the database.

Finally, we check if the response data is available and print the response code and string data to the Serial Monitor.

