To send arbitrary data from an Arduino to QGroundControl via PX4, you can use the Mavlink protocol. Here is an example source code:
```c
#include <Wire.h>
#include <Adafruit_BMP280.h>
#include <FastSerial.h>
#include <FastMavlink.h>

Adafruit_BMP280 bmp;

void setup() {
  Serial.begin(57600);
  bmp.begin(0x76);  
}

void loop() {
  float temperature = bmp.readTemperature();
  float pressure = bmp.readPressure() / 100.0;

  // create a mavlink message
  mavlink_message_t msg;
  mavlink_msg_named_value_float_pack(1, 200, &msg, "temperature", temperature);

  // send the message via serial to PX4
  uint8_t buf[MAVLINK_MAX_PACKET_LEN];
  uint16_t len = mavlink_msg_to_send_buffer(buf, &msg);
  Serial.write(buf, len);

  // wait for 1 second
  delay(1000);
}
```
In this example, we use the Adafruit BMP280 sensor to measure temperature and pressure. We then create a mavlink message with the `mavlink_msg_named_value_float_pack` function, which packs the temperature value into a mavlink message with a "temperature" name. We then send the message via serial to PX4 using the `Serial.write` function.

To receive the mavlink message in QGroundControl, you will need to create a mavlink message listener or add a mavlink message to the vehicle telemetry stream using the MAVLink Inspector.

Yes, it is possible to implement a dynamic array (similar to a Python list) in C. Here's an example implementation:
```c
#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *arr;
    int capacity;
    int size;
} List;

List *list_new() {
    List *list = (List *) malloc(sizeof(List));
    list->arr = NULL;
    list->capacity = 0;
    list->size = 0;
    return list;
}

void list_append(List *list, int item) {
    if (list->size == list->capacity) {
        int new_capacity = list->capacity == 0 ? 1 : list->capacity * 2;
        list->arr = (int *) realloc(list->arr, new_capacity * sizeof(int));
        list->capacity = new_capacity;
    }
    list->arr[list->size] = item;
    list->size++;
}

int list_get(List *list, int index) {
    if (index < 0 || index >= list->size) {
        fprintf(stderr, "Index out of range\n");
        exit(1);
    }
    return list->arr[index];
}

void list_free(List *list) {
    free(list->arr);
    free(list);
}

int main() {
    List *list = list_new();
    list_append(list, 10);
    list_append(list, 20);
    list_append(list, 30);
    printf("%d\n", list_get(list, 1)); // Output: 20
    list_free(list);
    return 0;
}
```
In this implementation, the `List` struct contains a pointer to an array of integers (`arr`), the current capacity of the array (`capacity`), and the current size of the array (`size`). The `list_new()` function initializes the struct with a null pointer and zero capacity and size. The `list_append()` function adds an item to the end of the array, dynamically resizing the array if necessary. The `list_get()` function retrieves an item from the array at a specified index. The `list_free()` function frees the memory allocated for the array and the struct.

