Remote Procedure Call (RPC) is a protocol that allows a client to invoke a function that is executed on a remote server. The client sends a message to the server, requesting the execution of a particular function, along with any necessary arguments. The server receives the message, executes the function, and returns the result to the client. The client then receives the result and continues its execution.

Here's an example implementation of RPC in C using socket programming:

1. Client code:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int main() {
  int sock = socket(AF_INET, SOCK_STREAM, 0);
  struct sockaddr_in server_addr;
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(8080);
  inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

  connect(sock, (struct sockaddr*)&server_addr, sizeof(server_addr));

  // Send function name and arguments
  char buffer[1024];
  sprintf(buffer, "add 3 4");

  send(sock, buffer, strlen(buffer), 0);

  // Receive result
  recv(sock, buffer, 1024, 0);
  printf("Result: %s\n", buffer);

  close(sock);
  return 0;
}
```
2. Server code:
```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

int add(int a, int b) {
  return a + b;
}

int main() {
  int server_sock = socket(AF_INET, SOCK_STREAM, 0);
  struct sockaddr_in server_addr;
  server_addr.sin_family = AF_INET;
  server_addr.sin_port = htons(8080);
  inet_pton(AF_INET, "127.0.0.1", &server_addr.sin_addr);

  bind(server_sock, (struct sockaddr*)&server_addr, sizeof(server_addr));

  listen(server_sock, 5);

  while(1) {
    int client_sock = accept(server_sock, NULL, NULL);
    char buffer[1024];

    // Receive function name and arguments
    recv(client_sock, buffer, 1024, 0);

    // Parse function name and arguments
    char* token = strtok(buffer, " ");
    int a = atoi(strtok(NULL, " "));
    int b = atoi(strtok(NULL, " "));

    // Call function and send result
    int result;
    if (strcmp(token, "add") == 0) {
      result = add(a, b);
    }
    sprintf(buffer, "%d", result);
    send(client_sock, buffer, strlen(buffer), 0);

    close(client_sock);
  }

  close(server_sock);
  return 0;
}
```
In this example, the client sends a message to the server with the function name "add" and its arguments "3" and "4". The server receives the message, parses it to determine which function to call, and calls the "add" function with the provided arguments. The result is then sent back to the client, which prints it out.

The basic logic behind this implementation is to use socket programming to create a communication channel between the client and server programs. The client sends a message to the server with the function name and arguments, and the server receives the message, determines which function to call, and sends back the result. The functions themselves can be implemented in any way that is appropriate for the particular application.

