Yes, it is definitely possible to write the rule using JavaScript instead of TypeScript, and that may simplify the setup process. Here's how you can write the rule in JavaScript:
```js
module.exports = {
  meta: {
    type: 'problem',
    docs: {
      description: 'Enforce Readonly on Props in React components',
      category: 'Best Practices',
      recommended: true,
    },
    schema: [], // no options
  },

  create(context) {
    function isReadonlyType(type) {
      return type.type === 'TSReadonlyKeyword';
    }

    function checkPropNode(node) {
      if (node.type === 'TSPropertySignature' && node.key.name === 'props') {
        const type = node.typeAnnotation.typeAnnotation;
        if (type.type !== 'TSTypeLiteral') {
          context.report({
            node,
            message: 'Expected Props to have a TSTypeLiteral type annotation',
          });
          return;
        }
        const props = type.members;
        for (const prop of props) {
          if (prop.type === 'TSPropertySignature' && prop.key.name !== 'children') {
            const type = prop.typeAnnotation.typeAnnotation;
            if (!isReadonlyType(type)) {
              context.report({
                node: prop,
                message: 'Expected {{prop}} to be readonly',
                data: {
                  prop: prop.key.name,
                },
              });
            }
          }
        }
      }
    }

    return {
      TSInterfaceDeclaration(node) {
        if (node.superTypeParameters) {
          for (const param of node.superTypeParameters.params) {
            checkPropNode(param);
          }
        }
      },
    };
  },
};
```
