function printMatchingIds(file1, file2) {
  // Read the contents of the two files
  const contents1 = readFile(file1);
  const contents2 = readFile(file2);

  // Split the contents into lines
  const lines1 = contents1.split('\n');
  const lines2 = contents2.split('\n');

  // Create a map to store the IDs and values from the first file
  const values1 = new Map();
  for (const line of lines1) {
    const [id, value] = line.split(' ');
    values1.set(id, value);
