from django.contrib.auth.forms import UserCreationForm
from django.contrib.auth import authenticate, login, logout
from django.shortcuts import render, redirect
from django.contrib import messages
def register(request):
    if request.method == 'POST':
        form = UserCreationForm(request.POST)
        if form.is_valid():
            form.save()
            username = form.cleaned_data.get('username')
            messages.success(request, f'Account created for {username}!')
            return redirect('login')
    else:
        form = UserCreationForm()
    return render(request, 'accounts/register.html', {'form': form})
def user_login(request):
    if request.method == 'POST':
        username = request.POST.get('username')
        password = request.POST.get('password')
        user = authenticate(request, username=username, password=password)
        if user is not None:
            login(request, user)
            return redirect('home')
        else:
            messages.info(request, 'Username OR password is incorrect')
    context = {}
    return render(request, 'accounts/login.html', context)
def user_logout(request):
    logout(request)
    return redirect('login')
```
Here, we define three views: `register`, `user_login`, and `user_logout`. The `register` view handles both GET and POST requests. It uses Django's built-in `UserCreationForm` to create a new user account. If the form is valid, it saves the user account and redirects the user to the login page. If the form is invalid, it re-renders the registration form with the validation errors.

The `user_login` view handles both GET and POST requests. It authenticates the user based on the username and password submitted in the login form. If the authentication is successful, it logs in the user and redirects them to the home page. If the authentication is unsuccessful, it re-renders the login form with an error message.

