  const [currentPage, setCurrentPage] = useState(1);
  const numPages = Math.ceil(section.images.length / MAX_IMAGES_PER_PAGE);

  const handlePageChange = (newPage: number) => {
    setCurrentPage(newPage);
  };

  const swipeHandlers = useSwipeable({
    onSwipedLeft: () => {
      if (currentPage < numPages) {
        handlePageChange(currentPage + 1);
      }
    },
    onSwipedRight: () => {
      if (currentPage > 1) {
        handlePageChange(currentPage - 1);
      }
    },
  });

  const startIndex = (currentPage - 1) * MAX_IMAGES_PER_PAGE;
  const endIndex = Math.min(startIndex + MAX_IMAGES_PER_PAGE, section.images.length);

  return (
